'use strict';
const $=s=>document.querySelector(s);
const scope=location.pathname.replace(/index\.html$/,'').replace(/\/$/,'')||'/';
const KEY='haru-hub-links-v1:'+scope,FAV='haru-hub-favorites-v1:'+scope;
let storageAvailable=true;
function read(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback;}catch{storageAvailable=false;return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('브라우저 저장이 차단되어 저장하지 못했어요. 저장 허용 설정을 확인해 주세요.');return false;}}
function safeUrl(raw){const u=new URL(raw.trim());if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw Error('로그인 정보·검색 매개변수·#이 없는 HTTPS 기본 주소를 넣어 주세요.');return u.href;}
function validLink(v){try{return v&&typeof v.id==='string'&&typeof v.name==='string'&&v.name.trim().length>0&&v.name.length<=60&&['journal','diary','class'].includes(v.category)&&safeUrl(v.url)===v.url;}catch{return false;}}
const stored=read(KEY,[]);let links=Array.isArray(stored)?stored.filter(validLink):[];
const savedFavorites=read(FAV,[]);let favorites=new Set(Array.isArray(savedFavorites)?savedFavorites.filter(x=>typeof x==='string'):[]);
