const builtins=[{id:'topics',name:'오늘의 일기 주제',description:'관찰·마음·상상·성장·감사. 30가지 질문으로 첫 문장을 가볍게 열어요.',category:'diary',icon:'✦',tone:'orange',label:'30가지 주제'}, {id:'routine',name:'5분 일기 쓰기',description:'장면 떠올리기부터 마지막 한 문장까지, 작은 단계로 차근차근 써봐요.',category:'diary',icon:'✎',tone:'green',label:'쓰기 길잡이'}, {id:'benefits',name:'일기, 왜 쓰면 좋을까?',description:'기록의 좋은 점과 부담 없이 이어가는 방법을 아이의 눈높이로 알아봐요.',category:'diary',icon:'♧',tone:'lavender',label:'학생 · 교사 안내'}, {id:'timer',name:'조용한 수업 타이머',description:'1분·3분·5분·10분. 글쓰기와 생각할 시간을 차분하게 지켜줘요.',category:'class',icon:'◷',tone:'blue',label:'이름 입력 없이'}];
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function openExternal(url){window.open(safeUrl(url),'_blank','noopener,noreferrer');}
function journal(){return links.find(l=>l.category==='journal');}
function render(){
 const j=journal();$('#journal-open').textContent=j?`${j.name} 열기 ↗`:'내 일기장 연결하기 ↗';$('#journal-note').textContent=j?'기존 일기장으로 이동해요. 허브에는 일기 내용이 저장되지 않아요.':'기존 일기장 주소를 연결하면 여기서 바로 열 수 있어요.';
 const all=[...builtins,...links.map(l=>({...l,description:l.category==='journal'?'내가 만든 일기장으로 이동해요. 기록과 접근 권한은 기존 웹앱에서 관리합니다.':'직접 연결한 웹앱이에요. 새 창에서 원래 도구를 열어요.',icon:l.category==='journal'?'▤':'↗',tone:l.category==='class'?'blue':'orange',label:l.category==='journal'?'기존 일기장 · 외부 링크':'개인정보 미수집 · 사용자 확인'}))];
 const shown=all.filter(a=>(filter==='all'||(filter==='favorite'?favorites.has(a.id):filter==='diary'?['diary','journal'].includes(a.category):a.category===filter))&&`${a.name} ${a.description}`.includes(search));$('#app-count').textContent=`${all.length}개의 작은 도구`;$('#app-grid').replaceChildren();$('#empty').hidden=shown.length>0;
 for(const a of shown){const card=el('article','app-card');card.dataset.tone=a.tone;const top=el('div','card-top');top.append(el('span','app-icon',a.icon));const star=el('button','star',favorites.has(a.id)?'★':'☆');star.setAttribute('aria-label',a.name+' 즐겨찾기');star.setAttribute('aria-pressed',String(favorites.has(a.id)));star.addEventListener('click',()=>{const next=new Set(favorites);next.has(a.id)?next.delete(a.id):next.add(a.id);if(write(FAV,[...next])){favorites=next;render();}});top.append(star);card.append(top,el('h3','',a.name),el('p','',a.description));const bottom=el('div','card-bottom');bottom.append(el('span','badge',a.label));const open=el('button','card-open','열기 ↗');open.setAttribute('aria-label',a.name+' 열기');open.onclick=()=>a.url?openExternal(a.url):openTool(a.id);bottom.append(open);card.append(bottom);$('#app-grid').append(card);}
 renderSaved();
}
function renderSaved(){const holder=$('#saved-links');holder.replaceChildren();if(!links.length){holder.append(el('p','muted','아직 연결한 웹앱이 없어요. 기존 일기장 주소부터 추가해 보세요.'));return;}for(const l of links){const row=el('div','saved-item'),info=el('div','',l.name);info.append(el('small','',l.url));const del=el('button','delete','연결 해제');del.onclick=()=>{if(!confirm(`‘${l.name}’ 연결을 해제할까요? 원래 웹앱과 그 기록은 삭제되지 않습니다.`))return;const next=links.filter(x=>x.id!==l.id);if(write(KEY,next)){links=next;render();toast('허브의 연결만 해제했어요.');}};row.append(info,del);holder.append(row);}}
function openManager(type){$('#link-error').textContent='';if(type)$('#link-type').value=type;$('#manage-dialog').showModal();}
$('#manage').onclick=()=>openManager();$('#journal-open').onclick=()=>journal()?openExternal(journal().url):openManager('journal');
$('#link-form').onsubmit=e=>{e.preventDefault();try{const name=$('#link-name').value.trim();if(!name||name.length>60)throw Error('도구 이름을 1~60자로 입력해 주세요.');const category=$('#link-type').value,url=safeUrl($('#link-url').value);if(!$('#link-confirm').checked)throw Error('개인정보 안내를 확인해 주세요.');const existing=links.find(l=>l.url===url);if(existing&&existing.category!==category)throw Error('이미 연결한 주소예요. 기존 연결을 해제한 후 다시 등록해 주세요.');let next=links.filter(l=>l.url!==url&&!(category==='journal'&&l.category==='journal'));next.push({id:existing?.id||crypto.randomUUID(),name,url,category});if(write(KEY,next)){links=next;render();$('#link-form').reset();toast('웹앱 주소를 이 브라우저에 연결했어요.');}else $('#link-error').textContent='저장하지 못했어요. 브라우저 저장 설정을 확인해 주세요.';}catch(error){$('#link-error').textContent=error.message;}};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(v=>{v.classList.toggle('active',v===b);v.setAttribute('aria-pressed',String(v===b));});render();});$('#search').oninput=e=>{search=e.target.value.trim();render();};
function topicText(){const t=topics[topicIndex];return `${t[1]}\n\n${t[2]}\n\n생각을 여는 질문\n${t.slice(3).map((q,i)=>`${i+1}. ${q}`).join('\n')}\n\n쓰고 싶지 않은 이야기는 쓰지 않아도 괜찮아요.`;}
function newTopic(){const pool=topics.map((t,i)=>({t,i})).filter(x=>topicFilter==='전체'||x.t[0]===topicFilter).map(x=>x.i).filter(i=>i!==topicIndex);if(pool.length)topicIndex=pool[Math.floor(Math.random()*pool.length)];renderTopic();}
function renderTopic(){const t=topics[topicIndex];$('#topic-title').textContent=t[1];$('#topic-hint').textContent=t[2];$('#topic-category').textContent=t[0];if($('#topic-sheet')){$('#topic-sheet').replaceChildren(el('span','overline',t[0]),el('h3','',t[1]),el('p','muted',t[2]));const list=el('ol');t.slice(3).forEach(q=>list.append(el('li','',q)));$('#topic-sheet').append(list);}}
async function copyTopic(){try{await navigator.clipboard.writeText(topicText());toast('주제를 복사했어요.');}catch{const body=$('#tool-body');$('#tool-title').textContent='주제 직접 복사';body.replaceChildren(el('p','','자동 복사를 사용할 수 없어요. 아래 내용을 선택해 복사해 주세요.'));const area=el('textarea','copy-fallback');area.value=topicText();area.readOnly=true;area.setAttribute('aria-label','복사할 일기 주제');body.append(area);if(!$('#tool-dialog').open)$('#tool-dialog').showModal();area.select();}}
function printTopic(){const area=$('#print-area'),t=topics[topicIndex];area.replaceChildren(el('small','','하루 한 줄 · 오늘의 일기 주제'),el('h1','',t[1]),el('p','',t[2]));const list=el('ol');t.slice(3).forEach(q=>list.append(el('li','',q)));area.append(list,el('p','','짧게 써도 좋아요. 쓰고 싶지 않은 이야기는 쓰지 않아도 괜찮아요.'));window.print();}
$('#next-topic').onclick=newTopic;$('#copy-topic').onclick=copyTopic;$('#print-topic').onclick=printTopic;
function openTool(id){const body=$('#tool-body');body.replaceChildren();$('#tool-title').textContent=builtins.find(a=>a.id===id)?.name||'저장과 개인정보 안내';
 if(id==='topics'){body.innerHTML='<p class="muted">마음에 드는 주제를 골라, 종이나 기존 일기장에 적어보세요. 이 도구에는 글을 입력하거나 제출하지 않습니다.</p><div class="topic-controls"><label for="topic-filter">주제 분류</label><select id="topic-filter"><option>전체</option><option>관찰</option><option>마음</option><option>상상</option><option>성장</option><option>감사</option></select><button class="button outline" id="modal-next">다른 주제 ↻</button></div><div class="topic-sheet" id="topic-sheet"></div><div class="modal-actions"><button class="button primary" id="modal-copy">주제 복사</button><button class="button outline" id="modal-print">인쇄</button></div><p class="field-hint">특정 경험이 떠오르지 않으면 상상한 이야기로 바꾸어 써도 좋아요.</p>';$('#topic-filter').value=topicFilter;$('#topic-filter').onchange=e=>{topicFilter=e.target.value;newTopic();};$('#modal-next').onclick=newTopic;$('#modal-copy').onclick=copyTopic;$('#modal-print').onclick=printTopic;renderTopic();}
 else if(id==='benefits'){body.innerHTML='<p class="muted">일기는 멋진 사건을 보고하는 숙제보다, 내 하루를 천천히 돌아보는 연습이 될 수 있어요.</p><h3>♡ 마음을 표현하는 말이 늘어나요</h3><p>‘기분이 좋았다’에서 ‘기다리던 일을 해내서 뿌듯했다’로. 내가 느낀 것을 구체적인 말로 바꿔보는 시간을 가질 수 있어요.</p><h3>✎ 생각의 순서를 연습해요</h3><p>무슨 일이 있었는지, 무엇을 느꼈는지, 다음에는 어떻게 하고 싶은지 이어 쓰며 생각을 정리해 봐요.</p><h3>♧ 작은 변화가 보여요</h3><p>지난 기록을 다시 읽으면 예전에는 어려웠던 일이 익숙해진 순간이나 생각이 달라진 점을 발견할 수 있어요.</p><h3>매일 쓰는 부담을 줄이는 약속</h3><ul><li>하루 한 문장부터 시작해요. 길이보다 내 말로 쓰는 경험이 먼저예요.</li><li>빠뜨린 날을 한꺼번에 채우지 않아도 괜찮아요. 오늘 다시 시작해요.</li><li>그림 한 장, 짧은 제목, 낱말 세 개로 출발해도 좋아요.</li><li>일기의 내용과 마음에 점수를 매기지 않아요.</li></ul><div class="modal-info"><h3>선생님과 함께 지킬 것</h3><p>가정의 사정, 연락처, 친구의 비밀을 쓰도록 요구하지 않아요. 보여주고 싶은 범위를 아이가 선택하게 해주세요. 일기만으로 아이의 마음을 단정하지 않고, 필요한 대화는 따로 나눠요.</p></div>';}
 else if(id==='routine'){body.innerHTML='<p class="muted">타이머에 맞추어 꼭 완성할 필요는 없어요. 편안한 속도로 한 단계씩 해봐요.</p>';[['1분','하나의 장면 고르기','오늘 본 것, 들은 말, 새롭게 해본 일 중 하나를 떠올려요.'],['1분','낱말 세 개 적기','그 장면의 색, 소리, 느낌을 떠오르는 말로 적어요.'],['2분','내 말로 이어 쓰기','“오늘 나는 …”으로 시작해 무슨 일이 있었고 어떤 마음이었는지 적어요.'],['1분','마지막 한 문장','“다음에는 …” 또는 “이 순간을 남기고 싶은 이유는 …”으로 마무리해요.']].forEach(([time,title,desc],i)=>{const row=el('div','step'),copy=el('div');copy.append(el('h3','',time+' · '+title),el('p','',desc));row.append(el('span','',String(i+1)),copy);body.append(row);});body.append(el('p','modal-info','선택한 장면이 마음에 들지 않으면 바꾸어도 좋아요. 글은 종이나 내 일기장에 적고, 이 허브에 입력하지 않아요.'));const button=el('button','button primary','5분 타이머 열기 →');button.onclick=()=>openTool('timer');body.append(button);}
 else if(id==='timer'){body.innerHTML='<p class="muted">생각할 시간을 조용히 지켜줘요. 화면이 꺼지거나 다른 탭을 보고 돌아와도 끝나는 시각을 기준으로 계산합니다.</p><div class="timer"><div class="timer-number" id="timer-number" aria-label="남은 시간"></div><p id="timer-state" role="status"></p><div class="preset"><button data-minutes="1">1분</button><button data-minutes="3">3분</button><button data-minutes="5">5분</button><button data-minutes="10">10분</button></div><div class="modal-actions"><button class="button primary" id="timer-toggle"></button><button class="button outline" id="timer-reset">다시 5분</button></div></div><p class="field-hint">알림 소리는 없어요. 끝나면 화면에 안내합니다. 페이지를 닫거나 새로고침하면 초기화됩니다.</p>';document.querySelectorAll('[data-minutes]').forEach(b=>b.onclick=()=>{stopTimer();remaining=Number(b.dataset.minutes)*60;renderTimer();});$('#timer-toggle').onclick=()=>{if(timerRunning){remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));stopTimer();}else{if(remaining<=0)remaining=300;timerEnd=Date.now()+remaining*1000;timerRunning=true;timer=setInterval(tick,250);}renderTimer();};$('#timer-reset').onclick=()=>{stopTimer();remaining=300;renderTimer();};tick();}
 else{body.innerHTML='<div class="privacy-box"><h3>이 허브가 저장하는 것</h3><p>직접 등록한 웹앱의 이름·주소·분류와 즐겨찾기를 이 브라우저의 로컬 저장소에 저장합니다. 학생 이름, 학번, 일기 내용, 제출 결과를 받거나 저장하는 기능은 없습니다.</p></div><h3>연결한 앱은 별개의 서비스예요</h3><p>일기장 버튼은 기존 웹앱을 새 창으로 엽니다. 허브가 원래 앱의 자료를 가져오거나 공개 범위를 바꾸지 않아요. 연결된 앱의 입력 항목과 개인정보 처리 방식은 원래 앱에서 확인하세요.</p><h3>다른 기기에서는 다시 연결해 주세요</h3><p>주소와 즐겨찾기는 서버에 동기화하지 않습니다. 브라우저 기록·사이트 데이터를 지우면 연결 목록이 사라질 수 있어요. 개인정보가 없는 링크만 등록해 주세요.</p><h3>접속 자체에 관하여</h3><p>이 허브에는 광고나 사용자 행동 분석 코드를 넣지 않았습니다. 사이트 접속과 접근 확인에는 호스팅 서비스가 제공하는 기능이 적용됩니다.</p>';}
 if(id==='privacy'){
   body.append(el('h3','','GitHub Pages에서 주의할 점'),el('p','','같은 GitHub Pages 도메인의 다른 프로젝트는 브라우저 저장 공간을 공유할 수 있어요. 도구 주소는 비밀 보관함이 아니므로 비밀번호, 비공개 초대 링크, 학생 정보가 담긴 주소를 넣지 마세요. Sites에서 저장한 목록은 이 주소로 자동 이전하지 않습니다.'));
   const policy=el('a','text-link','GitHub 개인정보 안내 ↗');policy.href='https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement';policy.target='_blank';policy.rel='noopener noreferrer';body.append(policy);
 }
 if(!$('#tool-dialog').open)$('#tool-dialog').showModal();
}
function stopTimer(){clearInterval(timer);timer=null;timerRunning=false;}
function tick(){if(timerRunning){remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(!remaining){stopTimer();toast('생각할 시간이 끝났어요. 편안하게 마무리해 주세요.');}}renderTimer();}
function renderTimer(){if(!$('#timer-number'))return;$('#timer-number').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;$('#timer-state').textContent=remaining===0?'시간이 끝났어요. 천천히 마무리해요.':timerRunning?'지금은 나의 생각 시간':'준비되면 시작해 주세요.';$('#timer-toggle').textContent=timerRunning?'잠깐 멈춤':remaining===0?'다시 시작':'시작';}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));$('#privacy').onclick=()=>openTool('privacy');document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
topicIndex=Math.floor(Date.now()/86400000)%topics.length;render();renderTopic();if(!storageAvailable)toast('브라우저 저장을 읽지 못했어요. 기본 도구는 계속 사용할 수 있어요.');
